def solve(text: str) -> str:
    a, b = map(int, text.split()[:2])
    cold = [[False] * 26 for _ in range(26)]
    for x in range(26):
        for y in range(26):
            if x == 0 and y == 0:
                cold[x][y] = False
                continue
            res = True
            for i in range(1, x + 1):
                if cold[x - i][y]:
                    res = False
                    break
            if res:
                for j in range(1, y + 1):
                    if cold[x][y - j]:
                        res = False
                        break
            if res:
                for i in range(1, min(x, y) + 1):
                    if cold[x - i][y - i]:
                        res = False
                        break
            cold[x][y] = res
    if cold[a][b]:
        return 'LOSE'
    for i in range(a + 1):
        for j in range(b + 1):
            if i == 0 and j == 0:
                continue
            if cold[a - i][b - j]:
                return 'WIN %d %d' % (i, j)
    return 'LOSE'
